// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: page-wide keys, view floating and copy buttons for reflex-kernel. Keys come from window.SHORTCUTS
//          (set from reflex_kernel/shortcuts.py, the one place they are defined):
//          FULL_SCREEN floats the view (.widget) you are in nearly full screen, or, outside a view,
//          fills the window with your pane (clicks its zoom button). CLOSE (Esc) closes a menu or
//          the help or debug panel, then a floating view. ADD_WIDGET clicks the hidden button that shows or hides the
//          "+" menu (a search box over the list: type to filter, arrows, Enter); in a menu, arrows move between its rows. TOGGLE_RESULTS / TOGGLE_PYTHON / HELP / DEBUG click the
//          bottom bar's pane toggles and the title bar's ? and bug icon (data-toggle). A view's float button (render.float_button) and
//          a click outside a floating view work too. reveal(id) scrolls to a chat row, result tab or
//          cell and flashes it (State.reveal).
// ---------------------------------------------------------------------------
(() => {
  const SHORTCUTS = window.SHORTCUTS || { FULL_SCREEN: "Alt+F", CLOSE: "Escape" };

  // "Alt+F" -> does this keydown match? Modifiers must match exactly; a letter matches by key position.
  const matches = (event, combo) => {
    const parts = combo.split("+");
    const key = parts.pop();
    const mods = new Set(parts);
    if (event.altKey !== mods.has("Alt") || event.ctrlKey !== mods.has("Ctrl")
      || event.shiftKey !== mods.has("Shift") || event.metaKey !== mods.has("Meta")) return false;
    return /^[A-Z]$/.test(key) ? event.code === `Key${key}` : event.key === key;
  };

  let lastTarget = null;
  const paneOf = (node) => (node instanceof Element ? node.closest("[data-pane]") : null);
  const visible = (node) => node && node.isConnected && node.offsetParent !== null;
  const floating = () => document.querySelector(".widget.is-floating");

  const setFloating = (widget, on) => {
    widget.classList.toggle("is-floating", on);
    document.body.classList.toggle("has-floating", on);
    // grids size themselves on resize
    window.dispatchEvent(new Event("resize"));
  };
  const toggleFloat = (widget) => {
    const current = floating();
    if (current && current !== widget) setFloating(current, false);
    setFloating(widget, !widget.classList.contains("is-floating"));
  };

  // State.reveal: scroll to an element (a chat row, a result tab, a cell) and flash it. The one
  // navigation of the app (Show in Chat, the debug log's links); the flash is .is-flash in
  // app.css, on the element's [data-flash] part when it has one (eg a result row, not its view)
  window.reveal = (id) => {
    const target = document.getElementById(id);
    if (!target) return;
    const current = floating();
    if (current) setFloating(current, false);
    target.scrollIntoView({ block: "center", inline: "nearest", behavior: "smooth" });
    const row = target.querySelector("[data-flash]") || target;
    row.classList.remove("is-flash");
    void row.offsetWidth; // restart the animation when flashed twice
    row.classList.add("is-flash");
    setTimeout(() => row.classList.remove("is-flash"), 1600);
  };

  document.addEventListener("pointerdown", (event) => {
    if (paneOf(event.target)) lastTarget = event.target;
    // a click outside the floating view puts it back (menus and popups float above it, so not those)
    const current = floating();
    if (current && !current.contains(event.target)
      && !event.target.closest(".menu, .help-panel, .debug-panel, .overlay-backdrop, .cm-tooltip, .gdg-overlay, #portal")) {
      setFloating(current, false);
    }
  }, true);

  // copy buttons (copy_button in reflex_kernel.py): copy data-copy, show a tick for a moment
  document.addEventListener("click", async (event) => {
    const button = event.target instanceof Element && event.target.closest(".copy-btn");
    if (!button) return;
    try {
      await navigator.clipboard.writeText(button.dataset.copy || "");
      button.classList.add("is-copied");
      setTimeout(() => button.classList.remove("is-copied"), 1400);
    } catch {
      button.title = "Couldn't copy (clipboard blocked)";
    }
  });

  document.addEventListener("click", (event) => {
    const button = event.target instanceof Element && event.target.closest(".float-btn");
    if (!button) return;
    const widget = button.closest(".widget");
    if (widget) toggleFloat(widget);
  });

  // a menu with a search box (reflex_kernel.menu_search): typing keeps the rows that have every
  // word and highlights the first; it starts with all rows, when the box takes focus on opening
  const menuRows = (search) => [...search.closest(".menu").querySelectorAll(".menu-item")];
  const filterMenu = (search) => {
    const words = search.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
    const rows = menuRows(search);
    rows.forEach((row) => { row.hidden = !words.every((word) => row.textContent.toLowerCase().includes(word)); });
    const shown = rows.filter((row) => !row.hidden);
    rows.forEach((row) => row.classList.toggle("is-active", row === shown[0]));
    search.closest(".menu").classList.toggle("is-empty", shown.length === 0);
  };
  document.addEventListener("input", (event) => {
    if (event.target.matches?.("[data-menu-search]")) filterMenu(event.target);
  });
  document.addEventListener("focusin", (event) => {
    if (event.target.matches?.("[data-menu-search]")) filterMenu(event.target);
  });

  // capture phase, so it also works while typing in a code cell or the chat box
  document.addEventListener("keydown", (event) => {
    if (matches(event, SHORTCUTS.CLOSE)) {
      const backdrop = document.querySelector(".overlay-backdrop");
      const current = floating();
      if (!backdrop && !current) return;
      event.preventDefault();
      event.stopPropagation();
      if (backdrop) backdrop.click();
      else setFloating(current, false);
      return;
    }
    // in a menu's search box: arrows move the highlighted row, Enter picks it
    if (event.target instanceof Element && event.target.matches("[data-menu-search]")) {
      const shown = menuRows(event.target).filter((row) => !row.hidden);
      const at = shown.findIndex((row) => row.classList.contains("is-active"));
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        event.stopPropagation();
        const next = shown[(at + (event.key === "ArrowDown" ? 1 : -1) + shown.length) % shown.length];
        shown.forEach((row) => row.classList.toggle("is-active", row === next));
        return;
      }
      if (event.key === "Enter") {
        event.preventDefault();
        event.stopPropagation();
        if (shown[at]) shown[at].click();
        return;
      }
    }
    // in a menu: arrows move between its rows (Enter runs the focused one, as any button)
    const item = document.activeElement instanceof Element && document.activeElement.closest(".menu .menu-item");
    if (item && (event.key === "ArrowDown" || event.key === "ArrowUp")) {
      event.preventDefault();
      event.stopPropagation();
      const items = [...item.closest(".menu").querySelectorAll(".menu-item")];
      const next = items.indexOf(item) + (event.key === "ArrowDown" ? 1 : -1);
      items[(next + items.length) % items.length].focus();
      return;
    }
    const toggle = [["TOGGLE_RESULTS", "results"], ["TOGGLE_PYTHON", "python"], ["HELP", "help"], ["DEBUG", "debug"], ["ADD_WIDGET", "add"]]
      .find(([name]) => SHORTCUTS[name] && matches(event, SHORTCUTS[name]));
    if (toggle) {
      const button = document.querySelector(`[data-toggle="${toggle[1]}"]`);
      if (button) {
        event.preventDefault();
        event.stopPropagation();
        button.click();
      }
      return;
    }
    if (!matches(event, SHORTCUTS.FULL_SCREEN)) return;
    event.preventDefault();
    event.stopPropagation();
    const current = floating();
    if (current) return setFloating(current, false);
    // where you are: the focused element, else the last thing clicked
    const here = [document.activeElement, lastTarget].find((node) => visible(paneOf(node)));
    const widget = here && here.closest(".widget");
    if (widget) return toggleFloat(widget);
    const zoomed = document.querySelector(".zoom-btn.is-on");
    const pane = here && paneOf(here);
    const button = zoomed || (pane && pane.querySelector(".zoom-btn")) || document.querySelector("[data-pane] .zoom-btn");
    if (button) button.click();
  }, true);
})();
